<script setup lang="ts">import{computed,onBeforeUnmount,ref,watch}from'vue';import{pairMethodsAt,PairMethods}from'../api';const p=defineProps<{busy:boolean;error:string;initialServer:string}>();const emit=defineEmits<{pair:[mode:'code'|'password',value:string,serverUrl:string]}>();const mode=ref<'code'|'password'>('code');const code=ref(''),password=ref(''),serverUrl=ref(p.initialServer),showPassword=ref(false),hasPassword=ref(false);let methodsTimer:number|undefined;const canSubmit=computed(()=>mode.value==='code'?code.value.replace(/\D/g,'').length===6:password.value.trim().length>=8);function submit(){const sv=serverUrl.value.trim();if(!sv||!canSubmit.value)return;const value=mode.value==='code'?code.value.replace(/\D/g,''):password.value.trim();emit('pair',mode.value,value,sv)}function onInput(e:Event){const target=e.target as HTMLInputElement;code.value=target.value.replace(/\D/g,'').slice(0,6)}async function fetchMethods(){const url=serverUrl.value.trim();if(!url){hasPassword.value=false;return}let parsed:URL;try{parsed=new URL(url)}catch{hasPassword.value=false;return}try{const m:PairMethods=await pairMethodsAt(parsed.origin);hasPassword.value=m.password;if(m.password&&mode.value==='code')mode.value='password'}catch{hasPassword.value=false}}watch(serverUrl,()=>{clearTimeout(methodsTimer);methodsTimer=window.setTimeout(fetchMethods,400)},{immediate:true});onBeforeUnmount(()=>clearTimeout(methodsTimer));</script>
<template><main class="pairing"><section class="pair-card"><img class="pair-logo" src="/icon.svg" alt="Codex Remote"><p class="eyebrow">CODEX REMOTE</p><h1>连接你的 Codex</h1><p>填写运行服务的电脑地址，选择配对方式并连接此设备。</p><label>服务器地址<input v-model="serverUrl" class="server-url-input" type="url" inputmode="url" autocomplete="url" placeholder="http://192.168.1.10:8787" @keyup.enter="submit"></label><div class="pair-tabs" role="tablist"><button type="button" role="tab" :class="['pair-tab',mode==='password'?'active':'']" :aria-selected="mode==='password'" @click="mode='password'">配对密码</button><button type="button" role="tab" :class="['pair-tab',mode==='code'?'active':'']" :aria-selected="mode==='code'" @click="mode='code'">配对码</button></div><label v-if="mode==='code'">配对码<input :value="code" maxlength="6" inputmode="numeric" autocomplete="one-time-code" placeholder="000000" @input="onInput" @keyup.enter="submit"></label><label v-else>配对密码<input v-model.trim="password" :type="showPassword?'text':'password'" inputmode="text" autocomplete="off" placeholder="输入设置好的配对密码" @keyup.enter="submit"><span class="password-toggle" @click="showPassword=!showPassword" role="button" tabindex="0" @keyup.enter="showPassword=!showPassword">{{showPassword?'隐藏':'显示'}}</span></label><button class="primary wide" :disabled="busy||!canSubmit||!serverUrl.trim()" @click="submit">{{busy?'正在连接…':mode==='password'?'用密码连接':'连接此设备'}}</button><p v-if="error" class="form-error">{{error}}</p><p v-if="mode==='password'&&hasPassword" class="pair-hint">使用配对密码连接的设备会在电脑重启后自动重连，无需再次输入密码。</p><p v-else-if="mode==='password'" class="pair-hint">若已在电脑端设置配对密码，可直接输入并连接；尚未设置时请在电脑端设置后再连接。</p><div class="pair-security"><span>◇</span><div><strong>私密且自托管</strong><small>访问凭据仅存储于本设备，不会显示在页面中，也不会发送到第三方。</small></div></div></section></main></template>
